import {predictCross} from './genetics.js?v=100';
import {getBreedingGuidance} from './breeding-guidance.js?v=121';

// These references describe virtual templates, never colony animals or tag zygosity.
export const BREEDING_PRESET_MODEL_VERSION='target-strategy-121:popular-plans-1';
const DEFAULT_TIMING=Object.freeze({founderReadyDay:0,breedingAgeDays:56,gestationDays:21,weaningAgeDays:21});
const FAMILY_DEFINITIONS=[
 {id:'pb',label:'PB′',locusIds:['per2-luc','bmal1'],codes:['P','B']},
 {id:'fpb',label:'FPB′',locusIds:['foxj1-cre','per2-luc','bmal1'],codes:['F','P','B']},
 {id:'adfpb',label:'ADFPB′',locusIds:['app-ps1','foxj1-cre','per2-luc','bmal1'],codes:['AD','F','P','B']}
];
const LOCUS_DEFINITIONS={
 'per2-luc':{name:'PER2::LUC',kind:'reporter',alleles:['+','PER2::LUC']},
 bmal1:{name:'Bmal1-flox',kind:'flox',alleles:['+','fl']},
 'foxj1-cre':{name:'FoxJ1-CreERT2',kind:'cre',alleles:['+','FoxJ1-Cre']},
 'app-ps1':{name:'APP/PS1',kind:'other',alleles:['+','APP/PS1']}
};
const clone=value=>structuredClone(value);
const own=(value,key)=>Object.prototype.hasOwnProperty.call(value||{},key);
const canonical=value=>JSON.stringify(value,(_,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.keys(v).sort().map(key=>[key,v[key]])):v);
const locusKeys=['id','name','kind','chromosome','alleles','wildTypeAllele','stockReference','stock_reference','stockNumber','referenceStock','stock','constraints','guidance'];
function modeledInput(input){
 const value={loci:(input?.loci||[]).map(locus=>Object.fromEntries(locusKeys.filter(key=>own(locus,key)).map(key=>[key,clone(locus[key])])))};
 for(const key of ['targets','sex','desiredCount','confidence','litterSize','independentAssortment','founders','timing','guidance'])if(own(input,key))value[key]=clone(input[key]);
 return value;
}
const guidanceFingerprint=input=>canonical((input?.loci||[]).map(locus=>getBreedingGuidance(locus)));
const modelKey=(input,fingerprint=guidanceFingerprint(input))=>canonical({model:BREEDING_PRESET_MODEL_VERSION,input:modeledInput(input),guidance:fingerprint});

export function popularBreedingPresets(catalogue=[]){
 return FAMILY_DEFINITIONS.map(family=>{
  const missing=[],loci=family.locusIds.map(id=>{
   const source=catalogue.find(row=>row?.id===id),definition=LOCUS_DEFINITIONS[id];
   if(!source||source.reviewRequired||source.name!==definition.name||source.kind!==definition.kind||!Array.isArray(source.alleles)||source.alleles.length!==2||!definition.alleles.every(allele=>source.alleles.includes(allele))){missing.push(definition.name);return null;}
   return {id,name:source.name,kind:source.kind,chromosome:source.chromosome,alleles:[...definition.alleles]};
  });
  return {...clone(family),label:canonicalCombinedGenotype(family.label)||family.label,loci:loci.filter(Boolean),missing};
 });
}
export function presetScenario(preset){
 if(!preset||preset.missing?.length||!preset.loci?.length)throw new Error('The required strains are not available in the current catalogue.');
 const loci=clone(preset.loci),unknown=()=>({alleles:[],evidence:'unknown'});
 return {loci,targets:Object.fromEntries(loci.map(locus=>[locus.id,{mode:'exact',alleles:[...locus.alleles]}])),sire:{sex:'Male',calls:Object.fromEntries(loci.map(locus=>[locus.id,unknown()]))},dam:{sex:'Female',calls:Object.fromEntries(loci.map(locus=>[locus.id,unknown()]))},sex:'Any',independentAssortment:false,desiredCount:1,confidence:.95,litterSize:6};
}
export function presetAssumptions(preset){return {founderCopies:Object.fromEntries(preset.loci.map(locus=>[locus.id,1])),wildTypeAvailable:true,timing:{...DEFAULT_TIMING}};}

/** Bounded, browser-memory-only cache. Its keys exclude animals and source metadata. */
let designer=null,designerLoading=null;
const defaultDesigner=input=>designer(input);
export function createBreedingPlanCache({design=defaultDesigner,maxEntries=8,maxBytes=1000000}={}){
 const memory=new Map();let used=0;
 return {get(input,{full=false,calculate=true}={}){
  const model=modeledInput(input),key=modelKey(model),cacheKey=(full?'full:':'quick:')+key;
  const stored=full?null:STORED_PLAN_INDEX.get(key);
  if(stored)return {result:clone(stored.result),cache:'stored'};
  if(memory.has(cacheKey)){const item=memory.get(cacheKey);memory.delete(cacheKey);memory.set(cacheKey,item);return {result:clone(item.result),cache:'memory'};}
  if(!calculate||design===defaultDesigner&&!designer)return {result:null,cache:'missing'};
  const result=design(model),bytes=new TextEncoder().encode(cacheKey+JSON.stringify(result)).byteLength;
  if(bytes<=maxBytes&&maxEntries>0){while(memory.size&&(memory.size>=maxEntries||used+bytes>maxBytes)){const oldest=memory.keys().next().value;used-=memory.get(oldest).bytes;memory.delete(oldest);}memory.set(cacheKey,{result:clone(result),bytes});used+=bytes;}
  return {result:clone(result),cache:'calculated'};
 },clear(){memory.clear();used=0;},get size(){return memory.size;}};
}
const cache=createBreedingPlanCache();
export const storedBreedingPlan=(input,options)=>cache.get(input,options);
export async function calculateBreedingPlan(input,{full=true}={}){
 const ready=cache.get(input,{full,calculate:false});if(ready.result)return ready.result;
 if(!designerLoading)designerLoading=import('./breeding-strategy.js?v=121').then(module=>{designer=module.designBreedingStrategy;return designer;}).catch(()=>{designerLoading=null;throw new Error('Route design could not load. Retry.');});
 await designerLoading;return cache.get(input,{full}).result;
}
export const defaultBreedingPlans=()=>PRECOMPUTED_PLANS.map(({family,input,result})=>({family,input:clone(input),result:clone(result)}));

// Parent families define explicit virtual calls, never observed colony genotypes.
export function commonFamilyCrosses(catalogue=[]){
 const presets=popularBreedingPresets(catalogue),rows=[];
 for(let sire=0;sire<presets.length;sire++)for(let dam=sire;dam<presets.length;dam++)rows.push({id:presets[sire].id+'-'+presets[dam].id,sire:presets[sire],dam:presets[dam],target:presets[dam],missing:[...new Set([...presets[sire].missing,...presets[dam].missing])]});
 return rows;
}
export function familyCrossScenario(cross,{reciprocal=false}={}){
 if(!cross||cross.missing?.length)throw new Error('The required strains are not available in the current catalogue.');
 const scenario=presetScenario(cross.target);scenario.independentAssortment=true;
 for(const [role,family]of [['sire',reciprocal?cross.dam:cross.sire],['dam',reciprocal?cross.sire:cross.dam]])scenario[role]={sex:role==='sire'?'Male':'Female',calls:Object.fromEntries(scenario.loci.map(locus=>[locus.id,{alleles:family.locusIds.includes(locus.id)?[...locus.alleles]:['+','+'],evidence:'inferred'}]))};
 return scenario;
}
const variantCopies=(parent,locus)=>{const pair=parent?.calls?.[locus.id]?.alleles;return Array.isArray(pair)&&pair.length===2&&pair.every(allele=>locus.alleles.includes(allele))?pair.filter(allele=>allele!=='+').length:null;};
export function familyCrossGuidance(scenario){
 const errors=[],warnings=[];
 for(const locus of scenario.loci||[]){
  const guide=getBreedingGuidance(locus);if(!guide)continue;
  for(const role of ['sire','dam']){const copies=variantCopies(scenario[role],locus),allowed=guide.constraints?.[role==='sire'?'sireAllowedCopies':'damAllowedCopies']??guide.constraints?.allowedCopies;
   if(copies!==null&&Array.isArray(allowed)&&!allowed.includes(copies))errors.push(`${locus.name}: ${role} with ${copies} variant copies is excluded by the exact-stock breeder restriction.`);
   if(copies===2&&guide.homozygousAdultViable!==false&&(guide.homozygousAdultViable===null||guide.homozygousFertile===null))warnings.push(`${locus.name}: homozygous ${role} viability or fertility is unverified. This is a conditional assumption.`);
  }
  const homozygotesPossible=variantCopies(scenario.sire,locus)>0&&variantCopies(scenario.dam,locus)>0,target=scenario.targets?.[locus.id],homozygousTarget=target?.mode==='exact'&&target.alleles?.length===2&&target.alleles.every(allele=>allele!=='+');
  if((homozygotesPossible||homozygousTarget)&&typeof guide.homozygousTargetWarning==='string')warnings.push(guide.homozygousTargetWarning);
 }
 return {errors:[...new Set(errors)],warnings:[...new Set(warnings)]};
}
function crossInput(scenario){const value=modeledInput(scenario);for(const role of ['sire','dam'])value[role]={sex:scenario[role]?.sex,calls:clone(scenario[role]?.calls||{})};return value;}
function crossKey(scenario,fingerprint=guidanceFingerprint(scenario)){return canonical({model:BREEDING_PRESET_MODEL_VERSION+':family-crosses-1',input:crossInput(scenario),guidance:fingerprint});}
function guidedCross(scenario){
 const result=predictCross(scenario),advice=familyCrossGuidance(scenario);result.warnings=[...new Set([...result.warnings,...advice.warnings])];
 if(advice.errors.length)return {...result,errors:[...new Set([...result.errors,...advice.errors])],targetProbability:null,genotypeTargetProbability:null,expectedPups:null,confidencePups:null,expectedLitters:null,confidenceLitters:null,outcomes:[],outcomeCount:0};
 return result;
}
function marginalTargets(scenario,result){return scenario.loci.map(locus=>{const target=scenario.targets?.[locus.id],pair=target?.mode==='exact'&&Array.isArray(target.alleles)?[...target.alleles].sort((a,b)=>locus.alleles.indexOf(a)-locus.alleles.indexOf(b)):null;return {id:locus.id,probability:result.outcomes.reduce((sum,outcome)=>sum+(!target||target.mode==='any'||target.mode==='carrier'&&outcome.calls[locus.id].includes(target.allele)||pair&&outcome.calls[locus.id].every((allele,index)=>allele===pair[index])?outcome.probability:0),0)};});}
function unpackCross(record,scenario){const result=clone(record.result);result.warnings=result.warnings.map(index=>COMMON_TEXT[index]);result.assumptions=result.assumptions.map(index=>COMMON_TEXT[index]);result.outcomes=result.outcomes.map(([copies,probability,meetsTarget])=>({calls:Object.fromEntries(scenario.loci.map((locus,index)=>[locus.id,copies[index]==='0'?['+','+']:copies[index]==='1'?[...locus.alleles]:[locus.alleles[1],locus.alleles[1]]])),probability,meetsTarget:Boolean(meetsTarget)}));return result;}
function reciprocalCross(scenario){const value=clone(scenario);value.sire={...clone(scenario.dam),sex:'Male'};value.dam={...clone(scenario.sire),sex:'Female'};return value;}
function storedCrossScenario(record){const pair=record.id.split('-'),input=clone(PRECOMPUTED_PLANS.find(plan=>plan.family===pair[1]).input),scenario={loci:input.loci,targets:input.targets,sex:input.sex,desiredCount:input.desiredCount,confidence:input.confidence,litterSize:input.litterSize,independentAssortment:true};
 for(const [role,familyId]of [['sire',pair[0]],['dam',pair[1]]]){const family=FAMILY_DEFINITIONS.find(item=>item.id===familyId);scenario[role]={sex:role==='sire'?'Male':'Female',calls:Object.fromEntries(scenario.loci.map(locus=>[locus.id,{alleles:family.locusIds.includes(locus.id)?[...locus.alleles]:['+','+'],evidence:'inferred'}]))};}return scenario;
}
export function createFamilyCrossCache({predict=guidedCross,maxEntries=8,maxBytes=1000000}={}){
 const memory=new Map();let used=0;
 return {get(scenario,{summary=false}={}){
  // Real identities are validated directly and never retained in this cache.
  if(scenario.sire?.id!==undefined||scenario.dam?.id!==undefined){const result=predict(scenario);return {result,perLocus:marginalTargets(scenario,result),cache:'calculated'};}
  const input=crossInput(scenario),key=crossKey(input),stored=STORED_CROSS_INDEX.get(key);
  if(stored)return {result:summary?{targetProbability:stored.result.targetProbability}:unpackCross(stored,input),perLocus:clone(stored.perLocus),cache:'stored'};
  if(memory.has(key)){const item=memory.get(key);memory.delete(key);memory.set(key,item);return {...clone(item.value),cache:'memory'};}
  const result=predict(input),value={result,perLocus:marginalTargets(input,result)},bytes=new TextEncoder().encode(key+JSON.stringify(value)).byteLength;
  if(bytes<=maxBytes&&maxEntries>0){while(memory.size&&(memory.size>=maxEntries||used+bytes>maxBytes)){const oldest=memory.keys().next().value;used-=memory.get(oldest).bytes;memory.delete(oldest);}memory.set(key,{value:clone(value),bytes});used+=bytes;}return {...clone(value),cache:'calculated'};
 },clear(){memory.clear();used=0;},get size(){return memory.size;}};
}
const familyCache=createFamilyCrossCache();
export const storedFamilyCross=(scenario,options)=>familyCache.get(scenario,options);
